	 startRace(kind:'bike'|'street'){const type=kind==='bike'?'bike':'car',v=this.vehicles.find(x=>x.type===type&&this.session.s.owned.includes(x.id));if(!v){this.session.notify(kind==='bike'?'Own a bicycle first':'Own a car first');return}this.riding=v;v.root.visible=true;delete this.session.s.completed['garaged:'+v.id];v.x=6;v.z=49;v.yaw=Math.PI;v.speed=0;v.root.position.set(v.x,0,v.z);v.root.rotation.y=v.yaw;this.session.s.x=v.x;this.session.s.z=v.z;this.player.root.visible=v.type==='bike';this.input.yaw=v.yaw+Math.PI;this.raceMode=kind;this.raceIndex=0;this.raceTime=0;this.raceCheckpoints=kind==='bike'?[{x:6,z:20},{x:-5,z:-9},{x:-5,z:-48},{x:6,z:-9},{x:6,z:49}]:[{x:6,z:4},{x:58,z:-9},{x:6,z:-9},{x:-58,z:-9},{x:-5,z:-58},{x:6,z:49}];if(!this.raceMarker){this.raceMarker=new T.Group();const ring=new T.Mesh(new T.TorusGeometry(2.2,.12,8,28),new T.MeshBasicMaterial({color:'#efb45f'}));ring.rotation.y=Math.PI/2;ring.position.y=2.2;const beam=new T.Mesh(new T.CylinderGeometry(.08,.3,5,8),new T.MeshBasicMaterial({color:'#efb45f',transparent:true,opacity:.35}));beam.position.y=2.5;this.raceMarker.add(ring,beam);this.worldRoot.add(this.raceMarker)}this.raceMarker.visible=true;this.updateRaceMarker();this.session.notify(kind==='bike'?'BIKE RACE STARTED':'STREET RACE STARTED','Follow the gold checkpoints. The clock is live.','success')}
