	 start(reset=false){if(reset)this.reset();this.creatorMode=false;this.running=true;this.externalMenu=false;this.session.close();this.input.clear();this.input.yaw=0;this.camera.position.set(this.session.s.x,3,this.session.s.z+6);this.sound.start();this.setInput();if(!this.session.s.intro){this.session.s.intro=true;this.session.notify('WELCOME TO SAINT MERCER','Explore, work, or take a risk. The city is yours to read.');void this.session.save(false)}this.onUpdate()}
