 syncActorVisuals(dt:number){const blend=1-Math.exp(-dt*18);for(const a of this.remotePlayers){a.timer=Math.max(0,a.timer-dt);if(!a.timer)a.walking=false;this.animate(a,a.walking?'Walk':'Idle',dt,a.walking?1:.8)}for(const a of [...this.actors,...this.police,...this.remotePlayers]){a.root.position.x+=(a.x-a.root.position.x)*blend;a.root.position.z+=(a.z-a.root.position.z)*blend;a.root.position.y+=(.17-a.root.position.y)*Math.min(1,dt*12)}}
