 vehicleBlocked(x:number,z:number,yaw:number,type:string,ignore=''){const f=this.vehicleFootprint(type),boundX=f.halfWidth*Math.abs(Math.cos(yaw))+f.halfLength*Math.abs(Math.sin(yaw)),boundZ=f.halfWidth*Math.abs(Math.sin(yaw))+f.halfLength*Math.abs(Math.cos(yaw));if(this.solids.some(b=>b.y>0&&b.h>1&&Math.abs(x-b.x)<b.w/2+boundX&&Math.abs(z-b.z)<b.d/2+boundZ))return true;for(const v of this.vehicles){if(v.id===ignore||!v.root.visible)continue;if(this.vehicleTouches(x,z,yaw,type,v.x,v.z,v.yaw,v.type))return true}for(const t of this.traffic){if(t.id===ignore||!t.root.visible)continue;if(this.vehicleTouches(x,z,yaw,type,t.x,t.z,t.yaw,'car'))return true}return false}
