	 if(this.aiming&&WEAPONS[s.weapon||'fists'].kind==='ranged')for(const a of this.actors.filter(a=>!['dre','bishop','vale'].includes(a.id)&&a.routine!=='rival')){const d=Math.hypot(s.x-a.x,s.z-a.z),ready=(s.completed['robReady:'+a.id]||0)<=s.playtime;if(ready&&d<4.5&&d<dist){dist=d;this.nearest='rob:'+a.id;this.prompt=`Rob ${NPCS.find(n=>n.id===a.id)?.name} · keep weapon aimed`}}
 if(this.riding){this.nearest='exit';this.prompt=`Exit ${VEHICLE_DEFS.find(d=>d.id===this.riding!.id)!.name}`;if(Math.hypot(s.x-11,s.z-49)<6&&this.session.s.completed['stolen:'+this.riding.id]){this.nearest='fence';this.prompt='Sell boosted ride to Ruiz'}}
