 loop(time:number){if(this.dead)return;if(this.artReview&&this.last){this.reviewFrames.push(time-this.last);if(this.reviewFrames.length>180)this.reviewFrames.shift();}const dt=Math.min((time-this.last)/1000,.05);this.last=time;this.fps=this.fps*.96+1/Math.max(.001,dt)*.04;this.accumulator+=dt;while(this.accumulator>=1/60){this.tick(1/60);this.accumulator-=1/60}if(!this.running)this.clock+=dt;if(this.marketStock){const f=storyState(this.session.s).flags;this.marketStock.visible=!f.includes('shipment_missing')||f.includes('shipment_restored')}this.updateCamera(dt);this.syncActorVisuals(dt);this.renderer.render(this.scene,this.camera);this.uiTime+=dt;if(this.uiTime>.1){this.uiTime=0;this.onUpdate()}this.raf=requestAnimationFrame(t=>this.loop(t))}
	 objective(){const s=this.session.s;if((s.dirtyCash||0)>0){if(s.heat>0)return{title:'Hot money',text:`Lose the ${Math.ceil(s.heat)}-star police response · $${s.dirtyCash} at risk`,x:s.x,z:s.z};return{title:'Stash the score',text:`Get $${s.dirtyCash} home before the street takes it`,x:-15,z:-38}}const j=JOBS.find(j=>j.id===s.active);if(j){const p=PLACES.find(p=>p.id===j.target)!;return {title:j.name,text:`Deliver to ${p.name}`,x:p.x,z:p.z}}const node=STORY_MOVES[storyState(s).stage];if(node&&s.discovered?.includes(node.place)){const p=PLACES.find(p=>p.id===node.place)!;const actor=p.id==='bishop'?this.actors.find(a=>a.id==='bishop'):p.id==='meeting'&&storyState(s).stage===16?this.actors.find(a=>a.id==='vale'):undefined;return{title:node.title,text:node.objective,x:actor?.x??p.x,z:actor?.z??p.z}}if(s.path==='sandbox'||!s.discovered?.length)return{title:'Explore Saint Mercer',text:'Work, train, trade, explore, or take a risk.',x:s.x,z:s.z};if(s.completed.first)return{title:'Make your next move',text:'Find work, build skills, explore The Towers',x:11,z:49};return{title:'Choose your next move',text:'Talk to someone or discover a place that catches your eye.',x:s.x,z:s.z}}
 dispose(){this.dead=true;this.session.disposed=true;cancelAnimationFrame(this.raf);this.input?.dispose();this.resizeObs?.disconnect();this.cleanup.forEach(f=>f());this.sound.dispose();this.scene.traverse(o=>{if(o instanceof T.Mesh){o.geometry.dispose();const ms=Array.isArray(o.material)?o.material:[o.material];for(const m of ms){(m as T.MeshStandardMaterial).map?.dispose();m.dispose()}}});this.renderer?.dispose();this.renderer?.domElement.remove();this.world?.free()}
